"use client";
import {
  GalleryInternalImage,
  GalleryInternalStyles,
  GalleryInternalControls,
  galleryDistance,
  galleryStyle,
  useGalleryEnvironment,
  useGalleryMotion,
  type GalleryInternalProps,
  type GalleryInternalItem,
} from "./gallery-shared";
export interface InfiniteDraggableGridItem extends GalleryInternalItem {}
export interface InfiniteDraggableGridProps extends GalleryInternalProps {
  items: readonly InfiniteDraggableGridItem[];
  rows?: number;
  gap?: number;
  cardWidth?: number;
  drag?: boolean;
  autoplay?: boolean;
  speed?: number;
}
export function InfiniteDraggableGrid({
  items,
  rows = 2,
  gap = 80,
  cardWidth = 220,
  drag = true,
  autoplay = false,
  speed = 0.15,
  index,
  defaultIndex,
  onChange,
  onSelect,
  height = 680,
  label = "Infinite draggable grid",
  className = "",
  style,
  renderCaption,
}: InfiniteDraggableGridProps) {
  const env = useGalleryEnvironment();
  const rowCount = Math.max(1, Math.min(4, Math.round(rows)));
  const width = Math.min(
    cardWidth,
    env.size.width * 0.47,
    ((env.size.height - 90 - (rowCount - 1) * gap) / rowCount) * 0.8,
  );
  const step = width + gap;
  const columns = Math.max(1, Math.ceil(items.length / rowCount));
  const motion = useGalleryMotion(
    columns,
    { index, defaultIndex, onChange, drag, autoplay, speed, sensitivity: step },
    env,
  );
  const repeat = Math.max(1, Math.ceil((env.size.width / step + 2) / columns));
  const slots = columns * repeat;
  return (
    <div
      ref={env.ref}
      {...motion.handlers}
      className={`z-ag ${className}`}
      data-gallery="infinite-draggable-grid"
      data-index={motion.current}
      data-phase={motion.phase.toFixed(4)}
      tabIndex={0}
      role="region"
      aria-label={label}
      style={galleryStyle(height, {
        userSelect: drag ? "none" : undefined,
        touchAction: drag ? "pan-y" : undefined,
        cursor: drag ? "grab" : undefined,
        ...style,
      })}
    >
      <GalleryInternalStyles />
      {items.length > 0 &&
        Array.from({ length: rowCount * slots }, (_, i) => {
          const row = Math.floor(i / slots),
            col = i % slots;
          const itemIndex = (row * columns + (col % columns)) % items.length;
          const item = items[itemIndex];
          const x = galleryDistance(col, motion.phase + row * 0.5, slots) * step;
          const y = (row - (rowCount - 1) / 2) * (width * 1.3 + gap) - 20;
          return (
            <button
              type="button"
              key={`${row}-${col}`}
              className="z-ag-card"
              data-gallery-card={i}
              tabIndex={col < columns ? 0 : -1}
              aria-label={item.title ?? `Image ${itemIndex + 1}`}
              onClick={(event) => {
                if (event.detail === 0 || !motion.moved.current) onSelect?.(item, itemIndex);
              }}
              style={{
                width,
                height: width * 1.3,
                borderRadius: 4,
                transform: `translate(-50%,-50%) translate(${x}px,${y}px)`,
              }}
            >
              <GalleryInternalImage item={item} />
              {renderCaption && (
                <span className="z-ag-caption">{renderCaption(item, itemIndex)}</span>
              )}
            </button>
          );
        })}
      <GalleryInternalControls
        current={motion.current}
        count={columns}
        onPrevious={() => motion.choose(Math.round(motion.phase) - 1)}
        onNext={() => motion.choose(Math.round(motion.phase) + 1)}
        paused={motion.paused}
        onPause={autoplay ? () => motion.setPaused(!motion.paused) : undefined}
      />
    </div>
  );
}
